create table if not exists roles(id integer primary key, name text unique);
create table if not exists users(id integer primary key, username text unique, full_name text, password_hash text, role text, active int default 1);
create table if not exists settings(key text primary key, value text);
create table if not exists designs(id integer primary key, name text unique, category text, description text, active int default 1, notes text);
create table if not exists products(id integer primary key, design_id int references designs(id), name text, notes text);
create table if not exists customers(id integer primary key, name text unique);
create table if not exists contract_workers(id integer primary key, full_name text, phone text, start_date text, status text default 'ACTIVE', notes text, opening_balance real default 0);
create table if not exists contract_worker_design_prices(id integer primary key, worker_id int references contract_workers(id), design_id int references designs(id), price real, effective_date text, end_date text, created_by text, notes text);
create table if not exists contract_worker_design_price_history(id integer primary key, worker_id int, design_id int, old_price real, new_price real, effective_date text, changed_by text, changed_at text, notes text);
create table if not exists payroll_periods(id integer primary key, label text, start_date text, end_date text, week_number int, calendar text default 'E.C.', status text default 'DRAFT');
create table if not exists contract_work(id integer primary key, period_id int references payroll_periods(id), worker_id int references contract_workers(id), unique(period_id,worker_id));
create table if not exists contract_work_items(id integer primary key, work_id int references contract_work(id), design_id int references designs(id), quantity real, unit_price real, customer_id int, remark text);
create table if not exists contract_worker_balances(id integer primary key, period_id int, worker_id int, previous_balance real, work_earned real, other_earnings real default 0, total_payable real, amount_paid real, closing_balance real, unique(period_id,worker_id));
create table if not exists contract_worker_payments(id integer primary key, period_id int, worker_id int, amount real, note text, paid_by text, paid_at text, unique(period_id,worker_id));
create table if not exists main_employees(id integer primary key, full_name text, department text, position text, monthly_gross real, payment_frequency text, start_date text, status text default 'ACTIVE', notes text);
create table if not exists main_employee_salary_history(id integer primary key, employee_id int, old_gross real, new_gross real, effective_date text, reason text, changed_by text);
create table if not exists main_employee_payroll(id integer primary key, period_id int, employee_id int, monthly_gross real, frequency text, due int, basic real, transport real, ot_hours real, ot_pay real, sun_hours real, sun_pay real, night_hours real, night_pay real, commission real, other_earnings real, absence real, other_deductions real, net_pay real, payment_status text default 'PENDING', remark text, unique(period_id,employee_id));
create table if not exists overtime_records(id integer primary key, period_id int, employee_id int, ot_type text, normal_end text, actual_end text, hours real, work_date text);
create table if not exists night_work_records(id integer primary key, period_id int, employee_id int, hours real, work_date text);
create table if not exists transport_records(id integer primary key, period_id int, employee_id int, transport real, expense real, other_allowance real);
create table if not exists commission_records(id integer primary key, period_id int, employee_id int, amount real, description text, customer_order text, remark text);
create table if not exists absence_records(id integer primary key, period_id int, employee_id int, absent_days real, deduction_amount real);
create table if not exists other_earnings(id integer primary key, period_id int, employee_id int, amount real, description text);
create table if not exists other_deductions(id integer primary key, period_id int, employee_id int, amount real, description text);
create table if not exists payroll_approvals(id integer primary key, period_id int, from_status text, to_status text, user text, at text, note text);
create table if not exists payroll_audit_logs(id integer primary key, at text, user text, action text, entity text, old_value text, new_value text, reason text);
create table if not exists payroll_adjustments(id integer primary key, period_id int, kind text, person_id int, amount real, description text, ref_period_id int, reason text, created_by text, created_at text);
create table if not exists sync_applied(op_id text primary key, device text, user text, at text, summary text, status text, message text);
create table if not exists sync_devices(device text primary key, last_push text, last_pull text, ops_pushed int default 0, ops_rejected int default 0);
